    const createPrompter = vi.fn(() => stubPrompter());
    const deps = stubDeps({ createPrompter });
    await expect(main(['node', 'product', 'intent'], deps)).rejects.toThrow(/pass --text/);
    expect(createPrompter).not.toHaveBeenCalled();
