  it('rejects with cannot approve and still writes the draft lines when gaps remain', async () => {
    const deps = stubDeps();
    await expect(
      main(['node', 'product', 'judge', '--text', SPARSE_DUMP, '--budget', '0', '--approve', 'Pat'], deps),
    ).rejects.toThrow(/^product judge: cannot approve — /);

