  it('rejects with the decomposition blockers when a scope statement is horizontal', async () => {
    const deps = stubDeps();
    await expect(
      main(['node', 'product', 'judge', '--text', BLOCKED_DUMP, '--budget', '0', '--approve', 'Pat'], deps),
    ).rejects.toThrow(/^product judge: /);
